// Gate on the grade written by GFIN Email Pre-Filter.
//
// Most target domains run Microsoft 365 or Google Workspace, which refuse to
// confirm mailbox existence. 'sendable_unverified' means MX is good but the
// mailbox is unconfirmable - that is the normal case here, not a red flag.
// The bounce handler is what proves deliverability after the fact.

// TEST MODE: while this is set, ONLY this provider_id can be emailed.
// 146 leads are already graded sendable, so without this lock a run would
// contact real prospects. Set to '' to resume normal sending.
const TEST_ONLY_PROVIDER_ID = '';

const ALLOWED = ['sendable', 'sendable_unverified'];
const MIN_CONFIDENCE = 60;

// PROVENANCE GATE. A grade alone is not enough. v1 enrichment built both the
// domain and the address from the same guess ('Servant Leader' ->
// servantleader.com), so the pre-filter's domain/company similarity check
// always passed and these graded 'sendable'. Similarity cannot detect this;
// only provenance can. Refuse any address whose domain was never evidenced.
const REQUIRE_EVIDENCED_DOMAIN = true;

// An evidenced DOMAIN is not an evidenced MAILBOX. osint_pattern rows carry a
// real domain with a {first}.{last} mailbox assembled on top - that is still a
// guess, and it is where the bounces after 17 Sep came from. Set this false
// only for a deliberate, small, monitored test of guessed mailboxes.
const REQUIRE_OBSERVED_MAILBOX = true;

const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';

const out = [];
let skipped = { no_email: 0, already_sent: 0, replied: 0, suppressed: 0, not_graded: 0, wrong_grade: 0, low_conf: 0 };

for (const item of $input.all()) {
  const j = item.json;
  const grade = String(j.sendability || '').toLowerCase();
  const status = String(j.email_send_status || '').toLowerCase();

  if (TEST_ONLY_PROVIDER_ID && String(j.provider_id || '') !== TEST_ONLY_PROVIDER_ID) { skipped.not_test_lead = (skipped.not_test_lead || 0) + 1; continue; }
  if (!ne(j.email)) { skipped.no_email++; continue; }
  if (ne(j.email_sent_at)) { skipped.already_sent++; continue; }
  if (ne(j.replied_at)) { skipped.replied++; continue; }
  if (status === 'unsubscribed' || status === 'bounced' || status === 'invalid_email') { skipped.suppressed++; continue; }
  if (!ne(grade)) { skipped.not_graded++; continue; }
  if (!ALLOWED.includes(grade)) { skipped.wrong_grade++; continue; }
  if (Number(j.email_confidence || 0) < MIN_CONFIDENCE) { skipped.low_conf++; continue; }
  if (REQUIRE_EVIDENCED_DOMAIN) {
    const src = String(j.email_source || '').toLowerCase();
    const dsrc = String(j.company_domain_source || '').trim();
    if (/unevidenced|pattern_guess/.test(src) && !dsrc) { skipped.unevidenced_domain = (skipped.unevidenced_domain || 0) + 1; continue; }
  }
  if (REQUIRE_OBSERVED_MAILBOX) {
    const src2 = String(j.email_source || '').toLowerCase();
    const observed = /site_scrape|scrape_verified|_verified|manual/.test(src2);
    if (!observed) { skipped.mailbox_not_observed = (skipped.mailbox_not_observed || 0) + 1; continue; }
  }

  out.push({ json: j });
}

console.log(`Sendable: ${out.length}. Skipped: ${JSON.stringify(skipped)}`);
return out;

// Cap outbound cold email volume per day (deliverability safety).
const DAILY_CAP = 25;
const sd = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (sd.emailDate !== today) {
  sd.emailDate = today;
  sd.emailsSentToday = 0;
}
const remaining = Math.max(0, DAILY_CAP - (sd.emailsSentToday || 0));
console.log(`Daily cap: ${sd.emailsSentToday || 0}/${DAILY_CAP} sent today, ${remaining} remaining`);
return $input.all().slice(0, remaining);

