// Merge the AI draft onto the lead and build both text and HTML bodies.
// The unsubscribe link carries this lead's provider_id; clicking it hits the
// 'GFIN Unsubscribe Handler' webhook, which writes email_send_status =
// 'unsubscribed' back to the Lead Pool. The send gate already blocks that value.
const UNSUB_BASE = 'https://awf.deeplearningintelligence.com/webhook/gfin-unsubscribe';

const lead = $('Loop Over Leads').item.json;
const ai = $json.output || $json;

// Capitalise the first letter here rather than relying on the model to comply.
const rawSubject = (ai.subject || 'Quick question on funding').trim();
const subject = rawSubject.charAt(0).toUpperCase() + rawSubject.slice(1);
const body = (ai.body || '').trim();

const pid = encodeURIComponent(String(lead.provider_id || ''));
const unsubUrl = UNSUB_BASE + '?pid=' + pid;

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const htmlBody = esc(body).replace(/\n/g, '<br>');

const html =
  '<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;' +
  'font-size:15px;line-height:1.55;color:#222">' +
  htmlBody +
  '<div style="margin-top:28px;font-size:12px;color:#999">' +
  'Not for you? <a href="' + unsubUrl + '" style="color:#999">Unsubscribe</a>.' +
  '</div></div>';

const text = body + '\n\n---\nNot for you? Unsubscribe: ' + unsubUrl;

return { json: Object.assign({}, lead, { subject, body, html, text, unsubscribe_url: unsubUrl }) };

// Emit ONLY the fields to write back, so the Sheets node can auto-map by name.
// Passing the whole lead through made the node depend on a hand-maintained
// column schema, which breaks whenever a column is added to the sheet.
const sd = $getWorkflowStaticData('global');
sd.emailsSentToday = (sd.emailsSentToday || 0) + 1;

const lead = $('Attach Email Draft').first().json;

return [{ json: {
  provider_id: lead.provider_id,
  email_sent_at: new Date().toISOString(),
  email_send_status: 'sent'
}}];

// Nodes inside the batch loop run once per batch, so $(...).all() returns only
// the LAST batch - this reported 'emails_sent: 1' on a run that sent 25.
// Walk every run index to get the true total.
const countRuns = (name) => {
  let n = 0;
  for (let r = 0; r < 500; r++) {
    let batch;
    try { batch = $(name).all(0, r); } catch (e) { break; }
    if (!batch || batch.length === 0) break;
    n += batch.length;
  }
  return n;
};

let sent = 0, invalid = 0;
try { sent = countRuns('Mark Email Sent'); } catch (e) {}
try { invalid = countRuns('Mark Email Invalid'); } catch (e) {}
return [{ json: { run_id: $execution.id, finished_at: new Date().toISOString(), emails_sent: sent, emails_invalid: invalid } }];
